                            disabled={lineLocked || Boolean(cartStorageRecovery)}
                            className="grid h-11 w-11 place-items-center text-slate-500"
                            aria-label={`إنقاص كمية ${item.nameAr}`}
                          >
                            <Minus className="h-3 w-3" />
                          </button>
                          <span className="min-w-8 text-center text-xs font-black text-slate-900">
                            {item.quantity.toLocaleString('ar-JO')}
                          </span>
                          <button
                            type="button"
                            disabled={
                              lineLocked ||
                              Boolean(cartStorageRecovery) ||
                              (item.maxAvailablePackages!==null&&item.quantity>=item.maxAvailablePackages)
                            }
                            onClick={() =>
                              onQuantityChange(
                                item.localLineId,
                                item.quantity + 1
                              )
                            }
                            className="grid h-11 w-11 place-items-center text-blue-700 disabled:text-slate-300"
                            aria-label={`زيادة كمية ${item.nameAr}`}
                          >
                            <Plus className="h-3 w-3" />
                          </button>
                        </div>
                        ) : <span className="text-[10px] font-black text-violet-700">{item.parcelInstances.length.toLocaleString('ar-JO')} طرد مكوّن</span>}
                        <p className="text-xs font-black text-orange-700">
                          {formatJod(
                            item.quantity * item.unitPriceInMinorUnits
                          )}
                        </p>
                      </div>
                    </div>
                  </div>
                </article>
                );
              })}
            </div>

            <div className="shrink-0 border-t border-slate-100 bg-slate-50 px-4 pb-[max(1rem,env(safe-area-inset-bottom))] pt-3 sm:p-5">
              {(isRefreshingSnapshot || snapshotNotice) && (
                <div
                  role="status"
                  className="mb-3 rounded-2xl border border-sky-200 bg-sky-50 p-3 text-[10px] font-bold leading-5 text-sky-900"
                >
                  {isRefreshingSnapshot
                    ? (items.every(item=>item.quantityTracked===false)?'جارٍ التحقق من السعر والتوفر اليدوي.':'جارٍ التحقق من سعر ومخزون السلة.')
                    : snapshotNotice}
                </div>
              )}
              {checkoutDisabled && (
                <div
                  role="alert"
                  className="mb-3 flex items-start justify-between gap-3 rounded-2xl border border-amber-200 bg-amber-50 p-3 text-[10px] font-bold leading-5 text-amber-900"
                >
                  <div className="flex items-start gap-2">
                    <AlertTriangle className="mt-0.5 h-4 w-4 shrink-0" />
                    <p>{checkoutBlockedMessage}</p>
                  </div>
                  {onRetryCheckoutSettings && (
                    <button
                      type="button"
                      onClick={onRetryCheckoutSettings}
                      className="flex min-h-11 shrink-0 items-center rounded-xl border border-amber-300 bg-white px-3 py-1.5 text-[10px] font-black text-amber-900"
                    >
                      إعادة المحاولة
                    </button>
                  )}
                </div>
              )}
              <div className="mb-3 flex items-start gap-2 rounded-2xl border border-violet-200 bg-violet-50 p-2.5 text-[10px] font-bold leading-5 text-violet-800 sm:mb-4 sm:p-3">
                <TicketPercent className="mt-0.5 h-4 w-4 shrink-0" />
                لديك كوبون خصم؟ ستتمكن من إدخاله والتحقق منه آمنًا في خطوة البيانات والدفع.
              </div>
              <div className="flex items-center justify-between">
                <div>
                  <p className="text-[10px] font-bold text-slate-400">
                    إجمالي السلة
                  </p>
                  <p className="mt-1 text-xl font-black text-slate-950">
                    {formatJod(subtotal)}
                  </p>
                </div>
                <div className="rounded-2xl bg-emerald-100 px-3 py-2 text-[10px] font-extrabold text-emerald-700">
                  {quantitySummary}
                </div>
              </div>

              <button
                type="button"
                onClick={onCheckout}
                disabled={checkoutDisabled || isRefreshingSnapshot || Boolean(cartStorageRecovery)}
                className="mt-3 flex w-full items-center justify-center gap-2 rounded-2xl bg-blue-700 px-5 py-3.5 text-sm font-black text-white shadow-lg shadow-blue-900/20 transition hover:bg-blue-800 disabled:cursor-not-allowed disabled:bg-slate-300 disabled:shadow-none sm:mt-4 sm:py-4"
              >
                {checkoutDisabled || isRefreshingSnapshot
                  ? 'إتمام الطلب غير متاح مؤقتًا'
                  : 'إتمام الطلب بدون تسجيل دخول'}
                <ArrowLeft className="h-4 w-4" />
              </button>

              <button type="button" onClick={onClose} className="mt-2 flex min-h-11 w-full items-center justify-center rounded-2xl border border-slate-200 bg-white px-5 py-3 text-xs font-black text-slate-700">
                متابعة التسوق
              </button>

              <div className="mt-3 hidden items-start gap-2 rounded-2xl border border-emerald-200 bg-emerald-50 p-3 text-[10px] font-bold leading-5 text-emerald-800 sm:flex">
                <LockKeyhole className="mt-0.5 h-4 w-4 shrink-0" />
                لا تحتاج حسابًا أو كلمة مرور. سيُحفظ الطلب أولًا في الإدارة،
                وبعدها يفتح ملخص واتساب.
              </div>
            </div>
          </>
        )}
      </aside>
    </div>
  );
}

customer-web/src/components/CategoryDraw.beforeText:
import { Check, LayoutGrid, Menu, PackageSearch, X } from 'lucide-react';
import { useEffect } from 'react';
import type { CatalogCategory } from '../types/catalog';
import {
  ALL_CATEGORY_VISUAL,
  getCategoryVisual,
} from './categoryVisuals';

interface CategoryDrawerProps {
  isOpen: boolean;
  categories: CatalogCategory[];
  selectedCategory: string;
  totalProducts: number;
  onClose: () => void;
  onSelect: (categoryId: string) => void;
}

export function CategoryDrawer({
  isOpen,
  categories,
  selectedCategory,
  totalProducts,
  onClose,
  onSelect,
}: CategoryDrawerProps) {
  useEffect(() => {
    if (!isOpen) return;

    const previousOverflow = document.body.style.overflow;
    document.body.style.overflow = 'hidden';
    const handleKeyDown = (event: KeyboardEvent) => {
      if (event.key === 'Escape') onClose();
    };
    window.addEventListener('keydown', handleKeyDown);

    return () => {
      document.body.style.overflow = previousOverflow;
      window.removeEventListener('keydown', handleKeyDown);
    };
  }, [isOpen, onClose]);

  const handleSelect = (categoryId: string) => {
    onSelect(categoryId);
    onClose();
  };

  const categoryItems = [
    {
      id: 'all',
      code: 'ALL',
      nameAr: 'جميع المنتجات',
      productCount: totalProducts,
      availableProductCount: totalProducts,
    },
    ...categories,
  ];

  return (
    <div
      className={`fixed inset-0 z-[60] transition ${
        isOpen ? 'pointer-events-auto' : 'pointer-events-none'
      }`}
      aria-hidden={!isOpen}
      inert={!isOpen}
    >
      <button
        type="button"
        aria-label="إغلاق قائمة الأقسام"
        onClick={onClose}
        className={`absolute inset-0 bg-slate-950/60 backdrop-blur-sm transition-opacity duration-300 ${
          isOpen ? 'opacity-100' : 'opacity-0'
        }`}
      />

      <aside
        role="dialog"
        aria-modal="true"
        aria-labelledby="category-drawer-title"
        className={`absolute right-0 top-0 flex h-full w-[min(92vw,390px)] flex-col overflow-hidden bg-white shadow-2xl transition-transform duration-300 ${
          isOpen ? 'translate-x-0' : 'translate-x-full'
        }`}
      >
        <header className="relative overflow-hidden bg-gradient-to-br from-[#081835] to-blue-800 px-5 pb-5 pt-4 text-white">
          <div className="absolute -left-12 -top-16 h-40 w-40 rounded-full bg-cyan-400/15 blur-2xl" />
          <div className="relative flex items-start justify-between gap-4">
            <div className="flex items-center gap-3">
              <span className="grid h-11 w-11 place-items-center rounded-2xl bg-white/10 ring-1 ring-white/15">
                <Menu className="h-5 w-5" />
              </span>
              <div>
                <p className="text-[10px] font-black text-cyan-200">
                  وصول سريع
                </p>
                <h2 id="category-drawer-title" className="mt-1 font-black">
                  أقسام المنتجات
                </h2>
              </div>
            </div>
            <button
              type="button"
              onClick={onClose}
              aria-label="إغلاق"
              className="grid h-10 w-10 place-items-center rounded-2xl bg-white/10 text-white transition hover:bg-white/20"
            >
              <X className="h-4 w-4" />
            </button>
          </div>
          <p className="relative mt-4 text-[11px] font-semibold leading-6 text-blue-100/75">
            اختر القسم وسننقلك مباشرة إلى منتجاته وأسعاره المتوفرة.
          </p>
        </header>

        <div className="flex-1 overflow-y-auto bg-slate-50/80 p-3">
          <div className="space-y-2">
            {categoryItems.map((category) => {
              const isAll = category.id === 'all';
              const visual = isAll
                ? ALL_CATEGORY_VISUAL
                : getCategoryVisual(category.code);
              const Icon = isAll ? LayoutGrid : visual.icon;
              const isSelected = selectedCategory === category.id;

              return (
                <button
                  type="button"
                  key={category.id}
                  aria-pressed={isSelected}
                  onClick={() => handleSelect(category.id)}
                  className={`group flex w-full items-center gap-3 rounded-3xl border p-3 text-right transition duration-200 ${
                    isSelected
                      ? 'border-blue-200 bg-white shadow-md shadow-blue-900/10'
                      : 'border-transparent bg-white/65 hover:border-slate-200 hover:bg-white'
                  }`}
                >
                  <span
                    className={`grid h-11 w-11 shrink-0 place-items-center rounded-2xl ${
                      isSelected
                        ? `bg-gradient-to-br ${visual.active} text-white`
                        : visual.accent
                    }`}
                  >
                    <Icon className="h-5 w-5" />
                  </span>
                  <span className="min-w-0 flex-1">
                    <span className="block truncate text-xs font-black text-slate-950">
                      {category.nameAr}
                    </span>
                    <span className="mt-1 block text-[9px] font-bold text-slate-400">
                      {category.productCount > 0
                        ? `${category.productCount.toLocaleString('ar-JO')} صنف`
                        : 'لا توجد أصناف حاليًا'}
                    </span>
                  </span>
                  {isSelected ? (
                    <span className="grid h-7 w-7 shrink-0 place-items-center rounded-full bg-emerald-100 text-emerald-700">
                      <Check className="h-3.5 w-3.5" />
                    </span>
                  ) : (
                    <PackageSearch className="h-4 w-4 shrink-0 text-slate-300 transition group-hover:text-blue-500" />
                  )}
                </button>
              );
            })}
          </div>
        </div>

        <footer className="border-t border-slate-100 bg-white px-5 py-4 text-center text-[9px] font-bold text-slate-400">
          الأقسام والعدادات متزامنة مع تطبيق الإدارة
        </footer>
      </aside>
    </div>
  );
}

customer-web/src/components/CategoryShow.beforeText:
import {ProductImage} from './ProductImage';
import { ImageOff } from 'lucide-react';
import type { CSSProperties } from 'react';
import type { CatalogCategory, CatalogProduct } from '../types/catalog';
import {
  ALL_CATEGORY_VISUAL,
  getCategoryVisual,
} from './categoryVisuals';
import { getCategoryPath } from '../utils/publicRoutes';

interface CategoryShowcaseProps {
  categories: CatalogCategory[];
  products: CatalogProduct[];
  selectedCategory: string;
  totalProducts: number;
  onSelect: (categoryId: string) => void;
}

interface CategoryCardData {
  id: string;
  name: string;
  count: number;
  code: string;
  coverUrl: string;
}

function CategoryCard({
  category,
  isSelected,
  index,
  onSelect,
}: {
  category: CategoryCardData;
  isSelected: boolean;
  index: number;
  onSelect: (id: string) => void;
}) {
  const resolvedVisual =
    category.id === 'all'
      ? ALL_CATEGORY_VISUAL
      : getCategoryVisual(category.code);
  const Icon = resolvedVisual.icon;

  return (
    <a
      href={category.id === 'all' ? '/products/' : getCategoryPath(category.code || category.id)}
      aria-current={isSelected ? 'page' : undefined}
      aria-label={`فتح قسم ${category.name}`}
      onClick={(event) => {
        event.preventDefault();
        onSelect(category.id);
      }}
      style={{ animationDelay: `${Math.min(index * 45, 540)}ms` } as CSSProperties}
      className={`category-card-enter group relative aspect-square w-full overflow-hidden rounded-2xl border bg-white text-right shadow-[0_12px_30px_-22px_rgba(15,23,42,0.55)] transition duration-300 hover:-translate-y-0.5 hover:shadow-[0_18px_36px_-22px_rgba(30,64,175,0.45)] focus-visible:outline-none focus-visible:ring-4 focus-visible:ring-blue-200 ${
        isSelected
          ? 'border-blue-600 ring-2 ring-blue-100'
          : 'border-slate-200/90 hover:border-blue-200'
      }`}
    >
      <span
        className={`absolute inset-0 grid place-items-center overflow-hidden bg-gradient-to-br ${resolvedVisual.active}`}
      >
        <span className="absolute inset-0 grid place-items-center text-white/30">
          {category.coverUrl ? (
            <ImageOff className="h-7 w-7" />
          ) : (
            <Icon className="h-10 w-10" />
          )}
        </span>
        {category.coverUrl && (
          <ProductImage src={category.coverUrl} alt="" imageClassName="absolute inset-0 h-full w-full object-cover transition duration-500 group-hover:scale-105" fallbackClassName="hidden" />
        )}
        <span className="absolute inset-0 bg-gradient-to-t from-slate-950/80 via-slate-950/10 to-transparent" />

        {isSelected && (
          <span
            className="absolute right-2 top-2 h-2.5 w-2.5 rounded-full border-2 border-white bg-blue-500 shadow-sm"
            aria-hidden="true"
          />
        )}

        <span className="absolute inset-x-2 bottom-2 rounded-xl bg-slate-950/65 px-2 py-1.5 text-center text-[10px] font-black leading-4 text-white shadow-sm backdrop-blur-sm sm:text-xs">
          <span className="line-clamp-2">
            {category.name}
          </span>
        </span>
      </span>
    </a>
  );
}

export function CategoryShowcase({
  categories,
  products,
  selectedCategory,
  totalProducts,
  onSelect,
}: CategoryShowcaseProps) {
  const firstCatalogImage =
    products.find((product) => Boolean(product.imageUrl))?.imageUrl ?? '';
  const categoryItems: CategoryCardData[] = [
    {
      id: 'all',
      name: 'جميع المنتجات',
      count: totalProducts,
      code: 'ALL',
      coverUrl: firstCatalogImage,
    },
    ...categories.map((category) => ({
      id: category.id,
      name: category.nameAr,
      count: category.productCount,
      code: category.code,
      coverUrl:
        category.imageUrl ||
        products.find(
          (product) =>
            product.categoryId === category.id && Boolean(product.imageUrl)
        )?.imageUrl ||
        '',
    })),
  ];

  return (
    <section aria-labelledby="catalog-categories-heading" className="mt-7">
      <div className="mb-6 rounded-[1.75rem] border border-slate-200 bg-gradient-to-l from-white to-blue-50/50 px-5 py-6 shadow-sm sm:px-7">
        <p className="text-[10px] font-black uppercase tracking-[0.18em] text-blue-600">
          وصول أسرع
        </p>
        <div className="mt-1 flex flex-wrap items-end justify-between gap-3">
          <div>
            <h3
              id="catalog-categories-heading"
              className="text-xl font-black text-blue-950 sm:text-2xl"
            >
              أقسام النواصرة لتجارة الجملة والمواد الغذائية
            </h3>
            <p className="mt-2 text-[11px] font-bold leading-5 text-slate-500">
              اختر القسم الذي تريده وسننقلك مباشرة إلى أصنافه المتوفرة
            </p>
          </div>
          <p className="rounded-full bg-white px-3 py-2 text-[10px] font-black text-slate-500 shadow-sm">
            {categories.length.toLocaleString('ar-JO')} قسم مرتبط بتطبيق الإدارة
          </p>
        </div>
      </div>

      <div
        data-testid="category-grid"
        className="grid grid-cols-3 gap-2.5 sm:grid-cols-4 sm:gap-3 lg:grid-cols-5 xl:grid-cols-6"
      >
        {categoryItems.map((category, index) => (
          <CategoryCard
            key={category.id}
            category={category}
            isSelected={selectedCategory === category.id}
            index={index}
            onSelect={onSelect}
          />
        ))}
      </div>
    </section>
  );
}

customer-web/src/components/CheckoutModa.beforeText:
import {storefrontCartUnit} from '../utils/storefrontUnits';
import {
  AlertTriangle,
  BadgePercent,
  CheckCircle2,
  ClipboardCheck,
  ClipboardPaste,
  ExternalLink,
  LoaderCircle,
  LockKeyhole,
  LocateFixed,
  MapPin,
  MapPinned,
  PackageCheck,
  ReceiptText,
  ShieldCheck,
  ShoppingBag,
  UserRoundCheck,
  X,
  Banknote,
  Smartphone,
  Save,
  Trash2,
  Truck,
} from 'lucide-react';
import { FormEvent, useEffect, useMemo, useState, useId, useRef, isValidElement, cloneElement, Children } from 'react';
import {useDialogFocus} from '../hooks/useDialogFocus';
import {
  previewGuestPromotionV2,
} from '../services/orders.service';
import { CheckoutRecoveryCoordinator } from '../services/checkoutRecoveryCoordinator';
import { CartItem } from '../types/catalog';
import {
  CheckoutErrors,
  CheckoutField,
  DeliveryZone,
  GuestCheckoutForm,
  GuestOrderReceipt,
  GuestPaymentMethod,
  GuestPromotionQuoteV2,
  PersistedCheckoutAttemptV2,
} from '../types/checkout';
import {
  EMPTY_GUEST_CHECKOUT_FORM,
  buildGoogleMapsUrl,
  buildGuestOrderV2Lines,
  buildWhatsAppOrderMessage,
  buildWhatsAppUrl,
  createPromotionContextKey,
  MAX_GUEST_ORDER_LINE_ITEMS,
  MAX_GUEST_DELIVERY_DETAILS_LENGTH,
  getOrCreateGuestOrderSessionId,
  extractGoogleMapsCoordinates,
  isSupportedGoogleMapsUrl,
  normalizePromotionCode,
  readSavedGuestCustomer,
  saveGuestCustomer,
  clearSavedGuestCustomer,
  saveLastGuestOrder,
  validateGuestCheckout,
} from '../utils/checkout';
import {
  formatCartQuantitySummary,
  calculateCartSubtotal,
} from '../utils/cart';
import { formatJod } from '../utils/money';
import {checkoutErrorMessage} from '../utils/checkoutErrorMessage';
import { CheckoutProgress } from './CheckoutProgress';
import { CheckoutReceiptPanel } from './CheckoutReceiptPanel';
import { TurnstileWidget } from './TurnstileWidget';
import type { TurnstileStatus } from './TurnstileWidget';
import { PublicStorefrontSettings } from '../types/storefront';

interface CheckoutModalProps {
  isOpen: boolean;
  items: CartItem[];
  storeWhatsAppNumber: string;
  storefrontSettings: PublicStorefrontSettings;
  settingsUnavailable: boolean;
  initialPromotionCode?: string;
  coordinator: CheckoutRecoveryCoordinator;
  onClose: () => void;
  onRetryStorefrontSettings: () => void;
  onOpenPrivacyPolicy: () => void;
  onOrderCreated: (
    receipt: GuestOrderReceipt,
    items: CartItem[]
  ) => void;
  onTrackOrder: (receipt: GuestOrderReceipt) => void;
}

const GOVERNORATES = [
  'إربد',
  'المفرق',
  'جرش',
  'عجلون',
  'الزرقاء',
  'عمان',
  'البلقاء',
  'مادبا',
  'الكرك',
  'الطفيلة',
  'معان',
  'العقبة',
];

interface FieldProps {
  label: string;
  required?: boolean;
  error?: string;
  children: React.ReactNode;
}

function Field({ label, required, error, children }: FieldProps) {
  const fieldId = useId();
  const errorId = `${fieldId}-error`;
  let controlId: string | undefined;
  const decorate = (nodes: React.ReactNode): React.ReactNode => Children.map(nodes, child => {
    if (!isValidElement<{id?: string; children?: React.ReactNode; 'aria-describedby'?: string}>(child)) return child;
    if (typeof child.type === 'string' && ['input', 'select', 'textarea'].includes(child.type)) {
      const id = child.props.id || fieldId;
      controlId ||= id;
      return cloneElement(child, {id,
        ...{'aria-required': required || undefined, 'aria-invalid': error ? true : undefined,
          'aria-describedby': [child.props['aria-describedby'], error ? errorId : null].filter(Boolean).join(' ') || undefined},
      });
    }
    return typeof child.type === 'string' && child.props.children
      ? cloneElement(child, {}, decorate(child.props.children)) : child;
  });
  const content = decorate(children);
  return (
    <div className="block">
      <label htmlFor={controlId} className="mb-2 block text-[11px] font-extrabold text-slate-700">
        {label}
        {required && <span className="mr-1 text-rose-500">*</span>}
      </label>
      {content}
      {error && (
        <span id={errorId} role="alert" className="mt-1.5 block text-[10px] font-bold text-rose-600">
          {error}
        </span>
      )}
    </div>
  );
}

const inputClassName =
  'w-full rounded-2xl border border-slate-200 bg-slate-50 px-4 py-3 text-sm font-bold text-slate-900 outline-none transition placeholder:text-slate-400 focus:border-blue-400 focus:bg-white focus:ring-4 focus:ring-blue-100';

export function CheckoutModal({
  isOpen,
  items,
  storeWhatsAppNumber,
  storefrontSettings,
  settingsUnavailable,
  initialPromotionCode = '',
  coordinator,
  onClose,
  onRetryStorefrontSettings,
  onOpenPrivacyPolicy,
  onOrderCreated,
  onTrackOrder,
}: CheckoutModalProps) {
  const [form, setForm] = useState<GuestCheckoutForm>(
    EMPTY_GUEST_CHECKOUT_FORM
  );
  const [errors, setErrors] = useState<CheckoutErrors>({});
  const focusValidationError = useRef(false);
  const [submitError, setSubmitError] = useState('');
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [receipt, setReceipt] = useState<GuestOrderReceipt | null>(null);
  const [submittedItems, setSubmittedItems] = useState<CartItem[]>([]);
  const [isLocating, setIsLocating] = useState(false);
  const [locationMessage, setLocationMessage] = useState('');
  const [showLocationFallback, setShowLocationFallback] = useState(false);
  const [locationMode, setLocationMode] = useState<'current' | 'different'>(
    'current'
  );
  const [isPastingLocation, setIsPastingLocation] = useState(false);
  const [promotionInput, setPromotionInput] = useState('');
  const [promotionQuote, setPromotionQuote] =
    useState<GuestPromotionQuoteV2 | null>(null);
  const [promotionContextKey, setPromotionContextKey] = useState('');
  const [promotionError, setPromotionError] = useState('');
  const [isApplyingPromotion, setIsApplyingPromotion] = useState(false);
  const [paymentMethod, setPaymentMethod] = useState<GuestPaymentMethod>('cash_on_delivery');
  const [deliveryZone, setDeliveryZone] = useState<DeliveryZone>('inside_ramtha');
  const [saveCustomerDetails, setSaveCustomerDetails] = useState(false);
  const [isReviewing, setIsReviewing] = useState(false);
  const [turnstileToken, setTurnstileToken] = useState('');
  const [turnstileResetSignal, setTurnstileResetSignal] = useState(0);
  const [turnstileStatus, setTurnstileStatus] = useState<TurnstileStatus>('loading');
  const [pendingAttempt, setPendingAttempt] = useState<PersistedCheckoutAttemptV2 | null>(
    () => {
      const snapshot = coordinator.read();
      return snapshot.attempt.status === 'VALID' ? snapshot.attempt.attempt : null;
    }
  );

  const displayedItems = receipt || pendingAttempt?.serverState === 'UNKNOWN'
    ? submittedItems
    : items;
  const quantitySummary = formatCartQuantitySummary(displayedItems);
  const subtotal = calculateCartSubtotal(displayedItems);
  const currentPromotionContextKey = useMemo(
    () => createPromotionContextKey(form.phone, items),
    [form.phone, items]
  );
  const activePromotionQuote =
    promotionQuote && promotionContextKey === currentPromotionContextKey
      ? promotionQuote
      : null;
  const checkoutBeforeDelivery = pendingAttempt?.serverState === 'UNKNOWN'
    ? (pendingAttempt.request.expectedQuote?.subtotalInMinorUnits ?? subtotal) -
      (pendingAttempt.request.expectedQuote?.discountInMinorUnits ?? 0)
    : activePromotionQuote?.totalInMinorUnits ?? subtotal;
  const selectedDeliveryFee = pendingAttempt?.serverState === 'UNKNOWN'
    ? pendingAttempt.request.expectedQuote?.deliveryFeeInMinorUnits ?? 0
    : deliveryZone === 'inside_ramtha'
      ? storefrontSettings.insideRamthaDeliveryFeeInMinorUnits
      : storefrontSettings.outsideRamthaDeliveryFeeInMinorUnits;
  const checkoutTotal = checkoutBeforeDelivery + selectedDeliveryFee;
  const whatsappUrl = useMemo(() => {
    if (!receipt) return '';
    return buildWhatsAppUrl(
      storeWhatsAppNumber,
      buildWhatsAppOrderMessage({
        receipt,
        items: displayedItems,
        paymentMethod,
      })
    );
  }, [displayedItems, paymentMethod, receipt, storeWhatsAppNumber]);

  useEffect(() => {
    if (!isOpen || receipt) return;
    let active = true;
    void coordinator.resume().then((outcome) => {
      if (!active) return;
      const snapshot = coordinator.read();
      const attempt = snapshot.attempt.status === 'VALID' ? snapshot.attempt.attempt : null;
      setPendingAttempt(attempt);
      if (snapshot.reviewReason) {
        setSubmitError('تحتاج حالة الحفظ المحلية إلى مراجعة قبل إرسال أي طلب جديد.');
        return;
      }
      if (!attempt) return;
      if (attempt.reviewRequired) {
        setSubmitError(attempt.reviewRequired.message);
        return;
      }
      if (attempt.serverState === 'SUCCEEDED' && attempt.receipt) {
        setSubmittedItems(attempt.submittedItems);
        setReceipt(attempt.receipt);
        if (outcome?.status === 'RECONCILED') {
          setSubmitError('');
          onOrderCreated(attempt.receipt, attempt.submittedItems);
        } else {
          setSubmitError(
            outcome?.status === 'BLOCKED_CART'
              ? 'تم تسجيل الطلب، لكن السلة المحفوظة تحتاج معالجة صريحة قبل إكمال تسويتها محليًا.'
              : 'تم تسجيل الطلب، لكن تسوية السلة ما زالت معلقة محليًا. لن يُعاد إرسال الطلب.'
          );
        }
        return;
      }
      if (attempt.serverState === 'UNKNOWN') {
        setForm(attempt.request.customer);
        setPaymentMethod(attempt.request.paymentMethod);
        setDeliveryZone(attempt.request.deliveryZone);
        setPromotionInput(attempt.request.promotionCode || '');
        setSubmittedItems(attempt.submittedItems);
        setIsReviewing(true);
        setSubmitError(
          'حالة محاولة سابقة غير معروفة. أعد التحقق الأمني ثم اضغط «التحقق من نفس الطلب»؛ لن ننشئ مفتاحًا جديدًا.'
        );
      }
    }).catch((error: unknown) => {
      if (!active) return;
      setSubmitError(error instanceof Error ? error.message : 'تعذر استرداد محاولة الطلب بأمان.');
    });
    return () => { active = false; };
  }, [coordinator, isOpen, onOrderCreated, receipt]);

  useEffect(() => {
    if (!isOpen || receipt || pendingAttempt?.serverState === 'UNKNOWN') return;
    const saved = readSavedGuestCustomer(window.localStorage);
    if (saved) {
      setForm(saved);
      setDeliveryZone(
        `${saved.city} ${saved.area}`.includes('الرمثا')
          ? 'inside_ramtha'
          : 'outside_ramtha'
      );
      setSaveCustomerDetails(true);
      setLocationMode(
        saved.latitude !== null && saved.longitude !== null
          ? 'current'
          : saved.googleMapsUrl
            ? 'different'
            : 'current'
      );
    }
  }, [isOpen, pendingAttempt?.serverState, receipt]);

  useEffect(() => {
    if (!settingsUnavailable || receipt) return;
    setIsReviewing(false);
    setTurnstileToken('');
    setSubmitError('تعذر التحقق من إعدادات الطلب والتوصيل. حاول مرة أخرى.');
  }, [receipt, settingsUnavailable]);

  useEffect(() => {
    if (!isOpen || receipt || !initialPromotionCode.trim()) return;
    const normalizedCode = normalizePromotionCode(initialPromotionCode);
    if (!normalizedCode) return;
    setPromotionInput(normalizedCode);
    setPromotionQuote(null);
    setPromotionContextKey('');
    setPromotionError('اضغط «تطبيق» بعد إدخال رقم الهاتف لتثبيت الخصم.');
  }, [initialPromotionCode, isOpen, receipt]);

  useEffect(() => {
    if (
      promotionQuote &&
      promotionContextKey &&
      promotionContextKey !== currentPromotionContextKey
    ) {
      setPromotionQuote(null);
      setPromotionContextKey('');
      setPromotionError(
        'تغير رقم الهاتف أو محتوى السلة؛ أعد تطبيق الرمز لحساب صحيح.'
      );
    }
  }, [
    currentPromotionContextKey,
    promotionContextKey,
    promotionQuote,
  ]);

  const setField = (field: CheckoutField, value: string) => {
    setForm((current) => ({ ...current, [field]: value }));
    setErrors((current) => ({ ...current, [field]: undefined }));
    setSubmitError('');
  };

  const handleMapUrlChange = (value: string) => {
    const coordinates = extractGoogleMapsCoordinates(value);
    setForm((current) => ({
      ...current,
      googleMapsUrl: value,
      latitude: coordinates?.latitude ?? null,
      longitude: coordinates?.longitude ?? null,
    }));
    setErrors((current) => ({
      ...current,
      googleMapsUrl: undefined,
    }));
    setLocationMessage('');
    setShowLocationFallback(false);
    setSubmitError('');
  };

  const handleLocationModeChange = (mode: 'current' | 'different') => {
    setLocationMode(mode);
    setForm((current) => ({
      ...current,
      googleMapsUrl: '',
      latitude: null,
      longitude: null,
    }));
    setErrors((current) => ({
      ...current,
      googleMapsUrl: undefined,
    }));
    setLocationMessage('');
    setShowLocationFallback(false);
    setSubmitError('');
  };

  const handlePasteMapUrl = async () => {
    if (!navigator.clipboard?.readText) {
      setErrors((current) => ({
        ...current,
        googleMapsUrl:
          'الصق رابط خرائط Google يدويًا في الخانة أدناه.',
      }));
      return;
    }

    setIsPastingLocation(true);
    try {
      const value = (await navigator.clipboard.readText()).trim();
      if (!isSupportedGoogleMapsUrl(value)) {
        setErrors((current) => ({
          ...current,
          googleMapsUrl:
            'الحافظة لا تحتوي رابط مشاركة صحيحًا من خرائط Google.',
        }));
        setLocationMessage('');
        return;
      }
      const coordinates = extractGoogleMapsCoordinates(value);
      handleMapUrlChange(value);
      setLocationMessage(
        coordinates
          ? 'تم لصق موقع التوصيل واستخراج الإحداثيات وتأكيدها.'
          : 'تم لصق رابط الموقع. الروابط المختصرة تبقى قابلة للفتح وتحتاج مراجعة الدبوس.'
      );
    } catch {
      setErrors((current) => ({
        ...current,
        googleMapsUrl:
          'تعذر قراءة الحافظة. الصق الرابط يدويًا في الخانة.',
      }));
    } finally {
      setIsPastingLocation(false);
    }
  };

  const handleUseCurrentLocation = () => {
    if (!navigator.geolocation) {
      setErrors((current) => ({
        ...current,
        googleMapsUrl: 'تحديد الموقع غير مدعوم على هذا الجهاز.',
      }));
      setShowLocationFallback(true);
      return;
    }

    setIsLocating(true);
    setLocationMessage('جارٍ تحديد موقعك بدقة...');
    setShowLocationFallback(false);
    setErrors((current) => ({
      ...current,
      googleMapsUrl: undefined,
    }));

    navigator.geolocation.getCurrentPosition(
      ({ coords }) => {
        const latitude = Number(coords.latitude.toFixed(6));
        const longitude = Number(coords.longitude.toFixed(6));
        setForm((current) => ({
          ...current,
          latitude,
          longitude,
          googleMapsUrl: buildGoogleMapsUrl(latitude, longitude),
        }));
        setLocationMode('current');
        setLocationMessage('تم تحديد موقعك وإرفاق رابط الخرائط بالطلب.');
        setShowLocationFallback(false);
        setIsLocating(false);
      },
      (error) => {
        const message =
          error.code === error.PERMISSION_DENIED
            ? 'إذن الموقع مرفوض في هذا المتصفح. فعّله من إعدادات الموقع ثم أعد المحاولة.'
            : error.code === error.TIMEOUT
            ? 'استغرق تحديد الموقع وقتًا طويلًا. حاول مرة أخرى.'
            : 'تعذر تحديد الموقع الحالي. ألصق رابط الخرائط يدويًا.';
        setErrors((current) => ({
          ...current,
          googleMapsUrl: message,
        }));
        setLocationMessage('');
        setShowLocationFallback(true);
        setIsLocating(false);
      },
      {
        enableHighAccuracy: true,
        timeout: 15000,
        maximumAge: 60000,
      }
    );
  };

  const handlePromotionChange = (value: string) => {
    setPromotionInput(value.toUpperCase());
    setPromotionQuote(null);
    setPromotionError('');
    setSubmitError('');
  };

  const handleApplyPromotion = async () => {
    const code = normalizePromotionCode(promotionInput);
    if (!/^[A-Z0-9_-]{3,32}$/.test(code)) {
      setPromotionError('اكتب رمزًا صحيحًا ثم اضغط تطبيق.');
      return;
    }

    setIsApplyingPromotion(true);
    setPromotionError('');
    try {
      const quote = await previewGuestPromotionV2(
        buildGuestOrderV2Lines(items),
        code,
        form.phone
      );
      setPromotionInput(quote.code);
      setPromotionQuote(quote);
      setPromotionContextKey(currentPromotionContextKey);
    } catch (error) {
      setPromotionQuote(null);
      setPromotionError(
        error instanceof Error
          ? error.message
          : 'تعذر التحقق من رمز الخصم.'
      );
    } finally {
      setIsApplyingPromotion(false);
    }
  };

  const handleRemovePromotion = () => {
    setPromotionInput('');
    setPromotionQuote(null);
    setPromotionContextKey('');
    setPromotionError('');
  };

  const validateForReview = () => {
    setSubmitError('');
    if (isSubmitting || receipt) return;
    if (settingsUnavailable) {
      setSubmitError('تعذر التحقق من إعدادات الطلب والتوصيل. حاول مرة أخرى.');
      return false;
    }
    if (items.length === 0) {
      setSubmitError('السلة فارغة. أضف صنفًا قبل إرسال الطلب.');
      return false;
    }

    if (items.length > MAX_GUEST_ORDER_LINE_ITEMS) {
      setSubmitError(
        `الحد الأقصى للطلب هو ${MAX_GUEST_ORDER_LINE_ITEMS} صنفًا. احذف ${items.length - MAX_GUEST_ORDER_LINE_ITEMS} صنفًا على الأقل ثم حاول مرة أخرى.`
      );
      return false;
    }

    if (!storefrontSettings.ordersEnabled) {
      setSubmitError('الطلبات متوقفة مؤقتًا من إدارة المتجر. يمكنك التواصل معنا عبر واتساب.');
      return false;
    }

    if (subtotal < storefrontSettings.minimumOrderInMinorUnits) {
      setSubmitError(`الحد الأدنى للطلب هو ${formatJod(storefrontSettings.minimumOrderInMinorUnits)}. أضف أصنافًا أخرى للمتابعة.`);
      return false;
    }

    if (normalizePromotionCode(promotionInput) && !activePromotionQuote) {
      setPromotionError('اضغط «تطبيق» للتحقق من الرمز قبل إرسال الطلب.');
      return false;
    }

    const validationErrors = validateGuestCheckout(form);
    if (Object.keys(validationErrors).length > 0) {
      focusValidationError.current = true;
      setErrors(validationErrors);
      setSubmitError('راجع الحقول المطلوبة قبل إرسال الطلب.');
      return false;
    }

    if (
      deliveryZone === 'inside_ramtha' &&
      !`${form.governorate} ${form.city} ${form.area}`.includes('الرمثا')
    ) {
      focusValidationError.current = true;
      setErrors((current) => ({
        ...current,
        city: 'اكتب الرمثا أو اختر «خارج الرمثا» لحساب أجرة التوصيل الصحيحة.',
      }));
      setSubmitError('منطقة التوصيل لا تتطابق مع المدينة المدخلة.');
      return false;
    }

    return true;
  };

  const handleReview = (event: FormEvent) => {
    event.preventDefault();
    if (!validateForReview()) return;
    setIsReviewing(true);
  };

  const handleSubmit = async () => {
    const recoveryAttempt = pendingAttempt?.serverState === 'UNKNOWN' ? pendingAttempt : null;
    if (!recoveryAttempt && !validateForReview()) return;
    if (!turnstileToken) {
      setSubmitError('أكمل التحقق الأمني قبل إرسال الطلب.');
      return;
    }

    setIsSubmitting(true);
    setSubmitError('');
    let attempt: PersistedCheckoutAttemptV2 | null = recoveryAttempt;
    try {
      if (!attempt) {
        const lines = buildGuestOrderV2Lines(items);
        const authoritativeQuote = await previewGuestPromotionV2(
          lines,
          activePromotionQuote?.code,
          form.phone
        );
        const request = {
          contractVersion: 'phase3-customer-reservation-v2' as const,
          idempotencyKey: crypto.randomUUID(),
          clientSessionId: getOrCreateGuestOrderSessionId(window.sessionStorage),
          customer: structuredClone(form),
          items: lines,
          promotionCode: authoritativeQuote.code || undefined,
          paymentMethod,
          deliveryZone,
          expectedQuote: {
            subtotalInMinorUnits: authoritativeQuote.subtotalInMinorUnits,
            discountInMinorUnits: authoritativeQuote.discountInMinorUnits,
            deliveryFeeInMinorUnits: selectedDeliveryFee,
            totalInMinorUnits: authoritativeQuote.totalInMinorUnits + selectedDeliveryFee,
          },
        };
        attempt = await coordinator.prepare(request, items);
        setPendingAttempt(attempt);
      }
      const outcome = await coordinator.submit(attempt.attemptId, turnstileToken);
      const latest = coordinator.read();
      const latestAttempt = latest.attempt.status === 'VALID' ? latest.attempt.attempt : null;
      setPendingAttempt(latestAttempt);
      const result = 'receipt' in outcome ? outcome.receipt : undefined;
      if (result) {
        try {
          if (saveCustomerDetails) saveGuestCustomer(window.localStorage, form);
          else clearSavedGuestCustomer(window.localStorage);
          saveLastGuestOrder(
            window.localStorage,
            result.orderNumber,
            attempt.submittedItems
          );
        } catch {
          // Durable server-success evidence remains authoritative.
        }
        setSubmittedItems(attempt.submittedItems);
        setReceipt(result);
        if (outcome.status === 'RECONCILED') {
          onOrderCreated(result, attempt.submittedItems);
          setSubmitError('');
        } else {
          setSubmitError(
            outcome.status === 'BLOCKED_CART'
              ? 'تم تسجيل الطلب، لكن السلة المحفوظة تحتاج معالجة صريحة قبل إكمال تسويتها محليًا.'
              : outcome.status === 'SERVER_SUCCESS_MEMORY_ONLY'
                ? outcome.message
                : 'تم تسجيل الطلب، لكن تسوية السلة ما زالت معلقة محليًا. لن يُعاد إرسال الطلب.'
          );
        }

        const popup = window.open(
          buildWhatsAppUrl(
            storeWhatsAppNumber,
            buildWhatsAppOrderMessage({
              receipt: result,
              items: attempt.submittedItems,
              paymentMethod: attempt.request.paymentMethod,
            })
          ),
          '_blank',
          'noopener,noreferrer'
        );
        if (popup) popup.opener = null;
        return;
      }
      setTurnstileToken('');
      setTurnstileResetSignal((current) => current + 1);
      setSubmitError(
        outcome.status === 'UNKNOWN' || outcome.status === 'REJECTED'
          ? outcome.message
          : 'تحتاج محاولة الطلب إلى مراجعة قبل المتابعة.'
      );
    } catch (error) {
      const latest = coordinator.read();
      setPendingAttempt(latest.attempt.status === 'VALID' ? latest.attempt.attempt : null);
      setTurnstileToken('');
      setTurnstileResetSignal((current) => current + 1);
      setSubmitError(
        error instanceof Error
          ? error.message
          : 'تعذر إرسال الطلب. حاول مرة أخرى.'
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  const handleClose = () => {
