      setErrors({});
      setSubmitError('');
      setPromotionInput('');
      setPromotionQuote(null);
      setPromotionContextKey('');
      setPromotionError('');
      setLocationMessage('');
      setPaymentMethod('cash_on_delivery');
      setDeliveryZone('inside_ramtha');
