                  </p>
                </div>
                <div className="grid h-11 w-11 shrink-0 place-items-center rounded-2xl bg-violet-400/20 text-violet-200">
                  <BadgePercent className="h-5 w-5" />
                </div>
              </div>

              <button
                type="button"
