import {useEffect,useState} from 'react';
import {Modal} from '../../components/common/Modal';
import {RejectionNotice} from '../../components/common/RejectionNotice';
import {MoneyText,UiButton} from '../../components/ui';
import {useAuthStore} from '../../stores/useAuthStore';
import {hasNavigationRole} from '../more/adminNavigation.config';
import {PAYMENT_METHOD_LABELS} from '../orders/orderStatus';
import {correctionRecord,correctionRoles,correctionTitles,type CorrectionAction,type CorrectionPreview} from '../../utils/documentCorrection';
import {correctionRecovery,fetchCorrectionPreview,submitDocumentCorrection} from '../../services/supabase/documentCorrections.service';

function CorrectionDialog({action,recordId,onClose,onChanged}:{action:CorrectionAction;recordId:string;onClose:()=>void;onChanged:()=>void|Promise<void>}) {
  const [preview,setPreview]=useState<CorrectionPreview|null>(null),[reason,setReason]=useState('');
  const [loading,setLoading]=useState(true),[busy,setBusy]=useState(false),[error,setError]=useState(''),[recover,setRecover]=useState(false),[done,setDone]=useState(false);
  const load=async()=>{
    setLoading(true);setError('');setPreview(null);
    try{const saved=await correctionRecovery(action,recordId);if(saved){setPreview(saved.preview);setReason(saved.reason);setRecover(true);}else{setRecover(false);setPreview(await fetchCorrectionPreview(action,recordId));}}
    catch(e){setError(e instanceof Error?e.message:'تعذر تحميل المعاينة.');}
    finally{setLoading(false);}
  };
  useEffect(()=>{let active=true;void (async()=>{
    try{const saved=await correctionRecovery(action,recordId);if(!active)return;if(saved){setPreview(saved.preview);setReason(saved.reason);setRecover(true);}else{const p=await fetchCorrectionPreview(action,recordId);if(active)setPreview(p);}}
    catch(e){if(active)setError(e instanceof Error?e.message:'تعذر تحميل المعاينة.');}
    finally{if(active)setLoading(false);}
  })();return()=>{active=false;};},[action,recordId]);
  const submit=async()=>{
    if(busy||!preview)return;setBusy(true);setError('');
    try{await submitDocumentCorrection(action,recordId,recover?undefined:{preview,reason});setDone(true);setRecover(false);
      try{await onChanged();}catch{setError('نجح التصحيح؛ تعذر تحديث الشاشة. أعد تحميل المستند.');}}
    catch(e){setError(e instanceof Error?e.message:'تعذر التصحيح.');try{const saved=await correctionRecovery(action,recordId);setRecover(!!saved);}catch{setRecover(true);}}
    finally{setBusy(false);}
  };
  return <Modal isOpen title={correctionTitles[action]} onClose={onClose} closeDisabled={busy} trackChanges={false}>
    <div className="space-y-4" dir="rtl" aria-busy={busy} data-testid="document-correction-dialog">
      {loading&&<p role="status">جارٍ تحميل معاينة التصحيح…</p>}
      {error&&<RejectionNotice reason={error}/>}
      {done?<><p role="status">تم التصحيح وحُفظ أثره التدقيقي.</p><UiButton onClick={onClose}>إغلاق</UiButton></>:<>
        {preview&&<>
          <p className="font-bold">المستند: <bdi>{preview.reference}</bdi></p>
          {action!=='purchase_receipt'&&<p className="text-sm">القيمة الأصلية: <MoneyText amount={preview.effect.paymentInMinorUnits/1000} currency/> — {PAYMENT_METHOD_LABELS[preview.effect.paymentMethod??'']??'طريقة الدفع غير متاحة'}</p>}
          {recover?<p className="rounded-xl bg-nw-warn-bg p-3 text-sm">توجد محاولة محفوظة. استعد نتيجتها بنفس المفتاح والمدخلات؛ لا تبدأ محاولة جديدة.</p>
            :!preview.eligible?<RejectionNotice reason={preview.blockedReason} role="status"/>:<p className="text-sm text-nw-muted">معاينة من قاعدة البيانات؛ يعاد فحصها عند التأكيد.</p>}
          <dl className="space-y-2 rounded-xl border border-nw-border p-3 text-sm" aria-label="أثر التصحيح">
            {([['الكاش في الدرج','cashInMinorUnits'],['CliQ خارج الدرج','cliqInMinorUnits'],['دين العميل','customerDebtInMinorUnits'],['رصيد المورد','supplierBalanceInMinorUnits']] as const).map(([label,key])=><div className="flex justify-between gap-3" key={key}><dt>{label}</dt><dd><MoneyText amount={preview.effect[key]/1000} currency/></dd></div>)}
            <div className="flex justify-between gap-3"><dt>تغيّر المخزون بالوحدة الأساسية</dt><dd><bdi>{preview.effect.inventoryBaseUnits.toLocaleString('ar-JO')}</bdi></dd></div>
          </dl>
          {action==='purchase_receipt'&&<div className="text-xs text-nw-muted">{preview.effect.stock.filter(correctionRecord).map((row,i)=><p key={i}>{String(row.productName)} — متوسط التكلفة بعد الإلغاء: <bdi>{row.wacAfter===null?'غير محدد قبل الاستلام':String(row.wacAfter)}</bdi> فلس للوحدة.</p>)}<p>دفعات أمر الشراء العامة تبقى مقدّمة؛ تُعكس دفعات السند نفسه فقط.</p></div>}
          {(preview.eligible||recover)&&<label className="block space-y-2 text-sm font-semibold">سبب التصحيح<textarea aria-label="سبب التصحيح" value={reason} onChange={e=>setReason(e.target.value)} disabled={busy||recover} minLength={3} maxLength={500} rows={3} className="w-full rounded-xl border border-nw-border bg-nw-surface p-3 text-nw-text"/></label>}
        </>}
        <div className="flex flex-wrap gap-2">
          {(recover||preview?.eligible)&&<UiButton disabled={busy||loading||(!recover&&reason.trim().length<3)} onClick={()=>void submit()}>{busy?'جارٍ التصحيح…':recover?'استعادة نفس المحاولة':'تأكيد التصحيح'}</UiButton>}
          {!recover&&error&&<UiButton disabled={busy||loading} onClick={()=>void load()}>تحديث المعاينة</UiButton>}
          <UiButton disabled={busy} onClick={onClose}>إغلاق</UiButton>
        </div>
      </>}
    </div>
  </Modal>;
}
export function DocumentCorrectionAction({action,recordId,onChanged,insideMenu=false}:{action:CorrectionAction;recordId:string;onChanged:()=>void|Promise<void>;insideMenu?:boolean}) {
  const {roleName,roles}=useAuthStore(),[open,setOpen]=useState(false);
  if(!hasNavigationRole(correctionRoles[action],roleName,roles))return null;
  const trigger=<UiButton variant="plain" onClick={()=>setOpen(true)}>{correctionTitles[action]}</UiButton>;
  return <>
    {insideMenu?trigger:<details className="rounded-xl border border-nw-border px-3 text-sm"><summary className="min-h-11 cursor-pointer py-3" aria-label={`إجراءات ${correctionTitles[action]}`}>⋯</summary>{trigger}</details>}
    {open&&<CorrectionDialog action={action} recordId={recordId} onClose={()=>setOpen(false)} onChanged={onChanged}/>}
  </>;
}

src/features/dashboard/WidgetsSection.ts.beforeText:
/**
 * Nawasrah Business Manager - Executive Dashboard Widgets Section
 * Renders 5 live data widgets with direct quick triggers
 */

import React from 'react';
import {
  DashboardLatestOrder,
  DashboardLatestCustomer,
  DashboardLowStockAlert,
  DashboardInventoryMovement,
  DashboardNotificationItem,
} from '../../types/dashboard';
import { CURRENCY } from '../../constants';
import {
  ShoppingBag,
  Users,
  AlertTriangle,
  ArrowRightLeft,
  Bell,
  ChevronLeft,
  Plus,
  CheckCircle2,
  Clock,
} from 'lucide-react';

interface WidgetsSectionProps {
  latestOrders: DashboardLatestOrder[];
  latestCustomers: DashboardLatestCustomer[];
  lowStockAlerts: DashboardLowStockAlert[];
  recentInventoryMovements: DashboardInventoryMovement[];
  todayNotifications: DashboardNotificationItem[];
  onViewOrderDetails?: (orderId: string) => void;
  onReceiveStock?: (productId: string) => void;
  onNavigateToOrders?: () => void;
  onNavigateToProducts?: () => void;
  onNavigateToCustomers?: () => void;
}

const STATUS_BADGE_MAP: Record<string, { label: string; bg: string; text: string }> = {
  new: { label: 'جديد', bg: 'bg-nw-info-bg', text: 'text-nw-info border-nw-info/30' },
  confirmed: { label: 'مؤكد', bg: 'bg-nw-warn-bg', text: 'text-nw-warn border-nw-warn/30' },
  processing: { label: 'تجهيز', bg: 'bg-nw-info-bg', text: 'text-nw-info border-nw-info/30' },
  out_for_delivery: { label: 'توصيل', bg: 'bg-nw-info-bg', text: 'text-nw-info border-nw-info/30' },
  completed: { label: 'مكتمل', bg: 'bg-nw-ok-bg', text: 'text-nw-ok border-nw-ok/30' },
  delivered: { label: 'مكتمل', bg: 'bg-nw-ok-bg', text: 'text-nw-ok border-nw-ok/30' },
  cancelled: { label: 'ملغي', bg: 'bg-nw-bad-bg', text: 'text-nw-bad border-nw-bad/30' },
};

export const WidgetsSection: React.FC<WidgetsSectionProps> = ({
  latestOrders,
  latestCustomers,
  lowStockAlerts,
  recentInventoryMovements,
  todayNotifications,
  onViewOrderDetails,
  onReceiveStock,
  onNavigateToOrders,
  onNavigateToProducts,
  onNavigateToCustomers,
}) => {
  return (
    <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-3">
      {/* Widget 1: Latest Orders */}
      <div className="bg-nw-surface border border-nw-border p-4 rounded-2xl shadow-md space-y-3">
        <div className="flex items-center justify-between border-b border-nw-border pb-2">
          <div className="flex items-center gap-2">
            <ShoppingBag className="w-4 h-4 text-nw-info" />
            <h3 className="text-xs font-bold text-nw-text">أحدث الطلبات (Latest Orders)</h3>
          </div>
          <button
            onClick={onNavigateToOrders}
            className="text-[10px] font-semibold text-nw-info hover:underline flex items-center gap-0.5"
          >
            <span>جميع الطلبات</span>
            <ChevronLeft className="w-3 h-3" />
          </button>
        </div>

        <div className="space-y-2">
          {latestOrders.length === 0 ? (
            <div className="text-center py-6 text-nw-muted text-xs">لا توجد طلبات حديثة</div>
          ) : (
            latestOrders.slice(0, 5).map((o) => {
              const badge = STATUS_BADGE_MAP[o.status] || STATUS_BADGE_MAP.new;
              return (
                <div
                  key={o.id}
                  onClick={() => onViewOrderDetails?.(o.id)}
                  className="flex items-center justify-between bg-nw-bg p-2.5 rounded-xl border border-nw-border hover:border-nw-border transition cursor-pointer"
                >
                  <div>
                    <div className="flex items-center gap-2">
                      <span className="font-extrabold text-nw-text text-xs">#{o.orderNumber}</span>
                      <span
                        className={`text-[9px] font-bold px-2 py-0.5 rounded-full border ${badge.bg} ${badge.text}`}
                      >
                        {badge.label}
                      </span>
                    </div>
                    <span className="text-[10px] text-nw-muted block mt-0.5">{o.customerName}</span>
                  </div>
                  <div className="text-left">
                    <span className="font-extrabold text-nw-ok text-xs block">
                      {o.totalAmount.toFixed(3)} {CURRENCY}
                    </span>
                    <span className="text-[9px] text-nw-muted flex items-center gap-0.5">
                      <Clock className="w-2.5 h-2.5" />
                      {new Date(o.createdAt).toLocaleTimeString('ar-JO', { hour: '2-digit', minute: '2-digit' })}
                    </span>
                  </div>
                </div>
              );
            })
          )}
        </div>
      </div>

      {/* Widget 2: Latest Customers */}
      <div className="bg-nw-surface border border-nw-border p-4 rounded-2xl shadow-md space-y-3">
        <div className="flex items-center justify-between border-b border-nw-border pb-2">
          <div className="flex items-center gap-2">
            <Users className="w-4 h-4 text-nw-info" />
            <h3 className="text-xs font-bold text-nw-text">أحدث العملاء (Latest Customers)</h3>
          </div>
          <button
            onClick={onNavigateToCustomers}
            className="text-[10px] font-semibold text-nw-info hover:underline flex items-center gap-0.5"
          >
            <span>دليل العملاء</span>
            <ChevronLeft className="w-3 h-3" />
          </button>
        </div>

        <div className="space-y-2">
          {latestCustomers.length === 0 ? (
            <div className="text-center py-6 text-nw-muted text-xs">لا يوجد عملاء مضافون حديثاً</div>
          ) : (
            latestCustomers.map((c) => (
              <div
                key={c.id}
                className="flex items-center justify-between bg-nw-bg p-2.5 rounded-xl border border-nw-border"
              >
                <div className="flex items-center gap-2.5">
                  <div className="w-7 h-7 rounded-full bg-nw-info-bg text-nw-info font-bold flex items-center justify-center text-xs">
                    {c.fullName.charAt(0)}
                  </div>
                  <div>
                    <h4 className="font-bold text-nw-text text-xs">{c.fullName}</h4>
                    <span className="text-[10px] text-nw-muted">{c.phone || 'بدون هاتف'}</span>
                  </div>
                </div>
                <span className="text-[10px] bg-nw-surface-2 text-nw-text px-2 py-0.5 rounded-md font-semibold">
                  {c.governorate}
                </span>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Widget 3: Low Stock Alerts */}
      <div className="bg-nw-surface border border-nw-border p-4 rounded-2xl shadow-md space-y-3">
        <div className="flex items-center justify-between border-b border-nw-border pb-2">
          <div className="flex items-center gap-2">
            <AlertTriangle className="w-4 h-4 text-nw-warn" />
            <h3 className="text-xs font-bold text-nw-text">تنبيهات نواقص المخزون</h3>
          </div>
          <button
            onClick={onNavigateToProducts}
            className="text-[10px] font-semibold text-nw-warn hover:underline flex items-center gap-0.5"
          >
            <span>المخزون</span>
            <ChevronLeft className="w-3 h-3" />
          </button>
        </div>

        <div className="space-y-2 max-h-64 overflow-y-auto pr-0.5">
          {lowStockAlerts.length === 0 ? (
            <div className="text-center py-6 text-nw-ok text-xs font-semibold flex items-center justify-center gap-1.5">
              <CheckCircle2 className="w-4 h-4" />
              <span>المخزون بوضع ممتاز ولا توجد نواقص</span>
            </div>
          ) : (
            lowStockAlerts.map((p) => (
              <div
                key={p.id}
                className="flex items-center justify-between bg-nw-bg p-2.5 rounded-xl border border-nw-warn/40 text-xs"
              >
                <div>
                  <h4 className="font-bold text-nw-text">{p.nameAr}</h4>
                  <div className="flex items-center gap-2 text-[10px] mt-0.5">
                    <span className={p.isOutOfStock ? 'text-nw-bad font-extrabold' : 'text-nw-warn font-bold'}>
                      {p.isOutOfStock ? 'منتهي بالمخزن (0)' : `متبقي: ${p.availableQuantity} ${p.unit}`}
                    </span>
                    <span className="text-nw-muted">•</span>
                    <span className="text-nw-muted">حد الطلب: {p.reorderLevel}</span>
                  </div>
                </div>
                <button
                  onClick={() => onReceiveStock?.(p.id)}
                  className="bg-nw-warn-bg hover:bg-nw-warn-bg text-nw-warn text-[10px] font-bold px-2.5 py-1.5 rounded-lg border border-nw-warn/30 flex items-center gap-1 transition"
                >
                  <Plus className="w-3 h-3" />
                  <span>تزويد</span>
                </button>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Widget 4: Recent Inventory Movements */}
      <div className="bg-nw-surface border border-nw-border p-4 rounded-2xl shadow-md space-y-3">
        <div className="flex items-center justify-between border-b border-nw-border pb-2">
          <div className="flex items-center gap-2">
            <ArrowRightLeft className="w-4 h-4 text-nw-info" />
            <h3 className="text-xs font-bold text-nw-text">حركات المخزون الأخيرة</h3>
          </div>
        </div>

        <div className="space-y-2">
          {recentInventoryMovements.length === 0 ? (
            <div className="text-center py-6 text-nw-muted text-xs">لا توجد حركات مخزنية مسجلة</div>
          ) : (
            recentInventoryMovements.slice(0, 5).map((m) => (
              <div
                key={m.id}
                className="flex items-center justify-between bg-nw-bg p-2.5 rounded-xl border border-nw-border text-xs"
              >
                <div>
                  <h4 className="font-bold text-nw-text">{m.productName}</h4>
                  <span className="text-[10px] text-nw-muted block">{m.transactionType}</span>
                </div>
                <div className="text-left">
                  <span
                    className={`font-extrabold text-xs block ${
                      m.quantity > 0 ? 'text-nw-ok' : 'text-nw-bad'
                    }`}
                  >
                    {m.quantity > 0 ? `+${m.quantity}` : m.quantity}
                  </span>
                  <span className="text-[9px] text-nw-muted">
                    {new Date(m.createdAt).toLocaleTimeString('ar-JO', { hour: '2-digit', minute: '2-digit' })}
                  </span>
                </div>
              </div>
            ))
          )}
        </div>
      </div>

      {/* Widget 5: Today's Notifications & Audit Trail */}
      <div className="bg-nw-surface border border-nw-border p-4 rounded-2xl shadow-md space-y-3 lg:col-span-2">
        <div className="flex items-center justify-between border-b border-nw-border pb-2">
          <div className="flex items-center gap-2">
            <Bell className="w-4 h-4 text-nw-ok" />
            <h3 className="text-xs font-bold text-nw-text">إشعارات وسجلات عمليات اليوم</h3>
          </div>
        </div>

        <div className="space-y-2 max-h-60 overflow-y-auto pr-0.5">
          {todayNotifications.length === 0 ? (
            <div className="text-center py-6 text-nw-muted text-xs">لا توجد إشعارات مسجلة اليوم</div>
          ) : (
            todayNotifications.map((n) => (
              <div
                key={n.id}
                className="flex items-start justify-between bg-nw-bg p-2.5 rounded-xl border border-nw-border text-xs gap-2"
              >
                <div>
                  <h4 className="font-bold text-nw-ok">{n.action}</h4>
                  <p className="text-[11px] text-nw-text mt-0.5">{n.details}</p>
                </div>
                <span className="text-[9px] text-nw-muted whitespace-nowrap shrink-0">
                  {new Date(n.createdAt).toLocaleTimeString('ar-JO', { hour: '2-digit', minute: '2-digit' })}
                </span>
              </div>
            ))
          )}
        </div>
      </div>
    </div>
  );
};

src/features/inventory/InventoryOpeningS.beforeText:
import {WarehouseChoice} from '../../components/ui/WarehouseChoice';
import {SupplierReplacementSummary} from './SupplierReplacementSummary';
import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import {
  AlertTriangle,
  Boxes,
  CheckCircle2,
  ClipboardCheck,
  Download,
  FileSpreadsheet,
  History,
  Loader2,
  PackageCheck,
  Search,
  ShieldCheck,
  Upload,
  Warehouse as WarehouseIcon,
  X,
} from 'lucide-react';
import { useAppStore } from '../../stores/useAppStore';
import {useDialogFocus} from '../../hooks/useDialogFocus';
import {LEGACY_OPENING_LOOSE_HEADER} from '../../utils/legacyUnitImportHeaders';
import {
  applyInventoryOpeningSetupInSupabase,
  fetchInventoryOpeningSetupFromSupabase,
  type InventoryOpeningProduct,
  type InventoryOpeningSetup,
} from '../../services/supabase/inventory-opening.service';

interface InventoryOpeningSetupModalProps {
  onClose: () => void;
}

interface OpeningEntry {
  packageCount: string;
  looseUnits: string;
}

const emptyEntry = (): OpeningEntry => ({
  packageCount: '',
  looseUnits: '',
});

const createIdempotencyKey = () =>
  globalThis.crypto?.randomUUID?.() ||
  `opening-${Date.now()}-${Math.random().toString(36).slice(2)}`;

const integerValue = (value: string): number => {
  if (value.trim() === '') return 0;
  const parsed = Number(value);
  return Number.isInteger(parsed) && parsed >= 0 ? parsed : Number.NaN;
};

function escapeCsv(value: string | number): string {
  const text = String(value ?? '');
  return /[",\n\r]/.test(text) ? `"${text.replace(/"/g, '""')}"` : text;
}

function parseDelimitedText(content: string): string[][] {
  const firstLine = content.replace(/^\uFEFF/, '').split(/\r?\n/, 1)[0] || '';
  const delimiter = firstLine.includes('\t')
    ? '\t'
    : firstLine.split(';').length > firstLine.split(',').length
      ? ';'
      : ',';
  const rows: string[][] = [];
  let row: string[] = [];
  let cell = '';
  let quoted = false;

  for (let index = 0; index < content.length; index += 1) {
    const char = content[index];
    if (char === '"') {
      if (quoted && content[index + 1] === '"') {
        cell += '"';
        index += 1;
      } else {
        quoted = !quoted;
      }
    } else if (char === delimiter && !quoted) {
      row.push(cell.trim());
      cell = '';
    } else if ((char === '\n' || char === '\r') && !quoted) {
      if (char === '\r' && content[index + 1] === '\n') index += 1;
      row.push(cell.trim());
      if (row.some((value) => value !== '')) rows.push(row);
      row = [];
      cell = '';
    } else {
      cell += char;
    }
  }

  row.push(cell.trim());
  if (row.some((value) => value !== '')) rows.push(row);
  return rows;
}

const normalizedHeader = (value: string) =>
  value.replace(/^\uFEFF/, '').trim().toLowerCase().replace(/[\s_-]+/g, '');

const findHeaderIndex = (headers: string[], candidates: string[]) =>
  headers.findIndex((header) => candidates.includes(normalizedHeader(header)));

export const InventoryOpeningSetupModal: React.FC<
  InventoryOpeningSetupModalProps
> = ({ onClose }) => {
  const {
    warehouses,
    activeBranch,
    refreshProductsFromSupabase,
    refreshInventoryMovementsFromSupabase,
    setToast,
  } = useAppStore();
  const warehouseOptions = useMemo(
    () =>
      warehouses.filter(
        (warehouse) =>
          !activeBranch?.id || warehouse.branchId === activeBranch.id
      ),
    [activeBranch?.id, warehouses]
  );
  const [warehouseId, setWarehouseId] = useState(
    warehouseOptions[0]?.id || warehouses[0]?.id || ''
  );
  const [setup, setSetup] = useState<InventoryOpeningSetup | null>(null);
  const [entries, setEntries] = useState<Record<string, OpeningEntry>>({});
  const [searchQuery, setSearchQuery] = useState('');
  const [eligibleOnly, setEligibleOnly] = useState(false);
  const [notes, setNotes] = useState(
    'جرد افتتاحي فعلي عند بدء استخدام النظام'
  );
  const [isLoading, setIsLoading] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [showReview, setShowReview] = useState(false);
  const reviewPanel = useDialogFocus(showReview, () => { if (!isSubmitting) setShowReview(false); });
  const [loadError, setLoadError] = useState('');
  const [idempotencyKey, setIdempotencyKey] = useState(createIdempotencyKey);
  const fileInputRef = useRef<HTMLInputElement>(null);

  useEffect(() => {
    if (!warehouseId && warehouseOptions[0]?.id) {
      setWarehouseId(warehouseOptions[0].id);
    }
  }, [warehouseId, warehouseOptions]);

  const loadSetup = useCallback(async () => {
    if (!warehouseId) return;
    setIsLoading(true);
    setLoadError('');
    try {
      const result = await fetchInventoryOpeningSetupFromSupabase(warehouseId);
      setSetup(result);
      setEntries({});
    } catch (error) {
      const message =
        error instanceof Error
          ? error.message
          : 'تعذر تحميل تهيئة المخزون الافتتاحي.';
      setLoadError(message);
      setSetup(null);
    } finally {
      setIsLoading(false);
    }
  }, [warehouseId]);

  useEffect(() => {
    void loadSetup();
  }, [loadSetup]);

  const selectedRows = useMemo(() => {
    if (!setup) return [];
    return setup.products
      .filter((product) => {
        const entry = entries[product.productId];
        return Boolean(
          entry &&
            (entry.packageCount.trim() !== '' || entry.looseUnits.trim() !== '')
        );
      })
      .map((product) => {
        const entry = entries[product.productId] || emptyEntry();
        const packageCount = integerValue(entry.packageCount);
        const looseUnits = integerValue(entry.looseUnits);
        const actualQuantity =
          Number.isFinite(packageCount) && Number.isFinite(looseUnits)
            ? packageCount * product.unitsPerPackage + looseUnits
            : Number.NaN;
        const errors: string[] = [];
        if (!product.eligible) {
          errors.push(product.blockReason || 'الصنف غير مؤهل للرصيد الافتتاحي.');
        }
        if (!Number.isFinite(packageCount) || !Number.isFinite(looseUnits)) {
          errors.push('الكميات يجب أن تكون أعدادًا صحيحة موجبة أو صفرًا.');
        } else if (looseUnits >= product.unitsPerPackage) {
          errors.push(
            `المتبقي من ${product.baseUnitName} يجب أن يكون أقل من ${product.unitsPerPackage}.`
          );
        }
        if (actualQuantity > 0 && product.costPriceInMinorUnits <= 0) {
          errors.push('تكلفة الشراء غير مدخلة؛ عدّل بطاقة الصنف أولًا.');
        }
        return {
          product,
          packageCount,
          looseUnits,
          actualQuantity,
          difference: Number.isFinite(actualQuantity)
            ? actualQuantity - product.currentQuantity
            : Number.NaN,
          errors,
        };
      });
  }, [entries, setup]);

  const invalidRows = selectedRows.filter((row) => row.errors.length > 0);
  const totalActualQuantity = selectedRows.reduce(
    (sum, row) =>
      sum + (Number.isFinite(row.actualQuantity) ? row.actualQuantity : 0),
    0
  );
  const totalDifference = selectedRows.reduce(
    (sum, row) => sum + (Number.isFinite(row.difference) ? row.difference : 0),
    0
  );

  const filteredProducts = useMemo(() => {
    if (!setup) return [];
    const query = searchQuery.trim().toLowerCase();
    return setup.products.filter((product) => {
      const matchesSearch =
        !query ||
        product.productName.toLowerCase().includes(query) ||
        product.sku.toLowerCase().includes(query) ||
        product.barcode?.toLowerCase().includes(query);
      return matchesSearch && (!eligibleOnly || product.eligible);
    });
  }, [eligibleOnly, searchQuery, setup]);

  const updateEntry = (
    productId: string,
    field: keyof OpeningEntry,
    value: string
  ) => {
    if (value !== '' && !/^\d+$/.test(value)) return;
    setEntries((current) => ({
      ...current,
      [productId]: {
        ...(current[productId] || emptyEntry()),
        [field]: value,
      },
    }));
  };

  const clearEntry = (productId: string) => {
    setEntries((current) => {
      const next = { ...current };
      delete next[productId];
      return next;
    });
  };

  const downloadTemplate = () => {
    if (!setup) return;
    const header = [
      'SKU',
      'اسم الصنف',
      'عدد الطرود',
      'الباكيتات المتبقية',
      'محتوى الطرد',
      'نوع الطرد',
    ];
    const lines = setup.products.map((product) => [
      product.sku,
      product.productName,
      '',
      '',
      product.unitsPerPackage,
      'طرد',
    ]);
    const csv = `\uFEFF${[header, ...lines]
      .map((row) => row.map(escapeCsv).join(','))
      .join('\r\n')}`;
    const blob = new Blob([csv], { type: 'text/csv;charset=utf-8' });
    const url = URL.createObjectURL(blob);
    const link = document.createElement('a');
    link.href = url;
    link.download = `opening-stock-${setup.warehouse.name}.csv`;
    link.click();
    URL.revokeObjectURL(url);
  };

  const importTemplate = async (file: File) => {
    if (!setup) return;
    try {
      const rows = parseDelimitedText(await file.text());
      if (rows.length < 2) {
        throw new Error('الملف فارغ أو لا يحتوي أصنافًا.');
      }
      const headers = rows[0];
      const skuIndex = findHeaderIndex(headers, ['sku', 'رمزالصنف']);
      const packagesIndex = findHeaderIndex(headers, [
        'عددالطرود',
        'packages',
        'packagecount',
      ]);
      const looseIndex = findHeaderIndex(headers, [
        'الباكيتاتالمتبقية',
        LEGACY_OPENING_LOOSE_HEADER,
        'looseunits',
        'remainingpieces',
      ]);
      if (skuIndex < 0 || packagesIndex < 0 || looseIndex < 0) {
        throw new Error(
          'استخدم القالب المعتمد؛ الأعمدة المطلوبة: رمز الصنف، عدد الطرود، الباكيتات المتبقية.'
        );
      }

      const productsBySku = new Map<string, InventoryOpeningProduct>(
        setup.products.map(
          (product) =>
            [product.sku.trim().toLowerCase(), product] as [
              string,
              InventoryOpeningProduct,
            ]
        )
      );
      const importedEntries: Record<string, OpeningEntry> = {};
      let imported = 0;
      let ignored = 0;
      const problems: string[] = [];

      rows.slice(1).forEach((row, rowIndex) => {
        const sku = (row[skuIndex] || '').trim().toLowerCase();
        const packageText = (row[packagesIndex] || '').trim();
        const looseText = (row[looseIndex] || '').trim();
        if (!sku || (packageText === '' && looseText === '')) return;
        const product = productsBySku.get(sku);
        if (!product) {
          ignored += 1;
          problems.push(`السطر ${rowIndex + 2}: رمز الصنف غير موجود.`);
          return;
        }
        if (!/^\d+$/.test(packageText || '0') || !/^\d+$/.test(looseText || '0')) {
          ignored += 1;
          problems.push(`السطر ${rowIndex + 2}: كمية غير صحيحة.`);
          return;
        }
        const packageCount = Number(packageText || 0);
        const looseUnits = Number(looseText || 0);
        if (looseUnits >= product.unitsPerPackage) {
          ignored += 1;
          problems.push(`السطر ${rowIndex + 2}: كمية ${product.baseUnitName} تتجاوز محتوى الطرد.`);
          return;
        }
        importedEntries[product.productId] = {
          packageCount: String(packageCount),
          looseUnits: String(looseUnits),
        };
        imported += 1;
      });

      setEntries((current) => ({ ...current, ...importedEntries }));
      setToast(
        ignored > 0
          ? `تم استيراد ${imported} صنف وتجاهل ${ignored}. ${problems[0] || ''}`
          : `تم استيراد ${imported} صنف من ملف Excel بنجاح.`,
        ignored > 0 ? 'info' : 'success'
      );
    } catch (error) {
      setToast(
        error instanceof Error ? error.message : 'تعذر قراءة ملف المخزون.',
        'error'
      );
    } finally {
      if (fileInputRef.current) fileInputRef.current.value = '';
    }
  };

  const handleApply = async () => {
    if (
      !warehouseId ||
      selectedRows.length === 0 ||
      invalidRows.length > 0 ||
      notes.trim().length < 5 ||
      isSubmitting
    ) {
      return;
    }

    setIsSubmitting(true);
    try {
      const result = await applyInventoryOpeningSetupInSupabase({
        warehouseId,
        rows: selectedRows.map((row) => ({
          productId: row.product.productId,
          packageCount: row.packageCount,
          looseUnits: row.looseUnits,
        })),
        notes,
        idempotencyKey,
      });
      await Promise.all([
        refreshProductsFromSupabase(),
        refreshInventoryMovementsFromSupabase(),
      ]);
      setToast(`${result.message} رقم الجلسة: ${result.sessionNumber}`, 'success');
      setEntries({});
      setShowReview(false);
      setIdempotencyKey(createIdempotencyKey());
      await loadSetup();
    } catch (error) {
      setToast(
        error instanceof Error
          ? error.message
          : 'تعذر اعتماد المخزون الافتتاحي.',
        'error'
      );
    } finally {
      setIsSubmitting(false);
    }
  };

  return (
    <div aria-busy={isSubmitting} className="space-y-4 text-xs">
      <SupplierReplacementSummary />
      <div className="rounded-2xl border border-nw-info/30 bg-nw-surface-2 from-nw-info-bg to-nw-border p-4">
        <div className="flex items-start gap-3">
          <div className="flex h-11 w-11 shrink-0 items-center justify-center rounded-2xl bg-nw-info-bg text-nw-info">
            <Boxes className="h-5 w-5" />
          </div>
          <div>
            <h4 className="font-black text-nw-info">إدخال البضاعة الموجودة قبل تشغيل النظام</h4>
            <p className="mt-1 leading-5 text-nw-muted">
              أدخل العدد الفعلي مرة واحدة. لن ينشئ النظام فاتورة مورد أو مديونية،
              وستُحفظ كل الكميات كحركات افتتاحية مدققة.
            </p>
          </div>
        </div>
      </div>

      <div className="grid gap-3 lg:grid-cols-[1fr_auto]">
        <label className="space-y-1.5">
          <span className="flex items-center gap-1.5 font-bold text-nw-text">
            <WarehouseIcon className="h-3.5 w-3.5 text-nw-info" />
            المستودع الذي تم جرده
          </span>
          <WarehouseChoice options={warehouseOptions} branchId={activeBranch?.id} value={warehouseId} onSingle={setWarehouseId}>
          <select
            value={warehouseId}
            onChange={(event) => setWarehouseId(event.target.value)}
            className="w-full rounded-xl border border-nw-border bg-nw-bg px-3 py-2.5 font-bold text-nw-text focus:border-nw-info focus:outline-none"
          >
            {warehouseOptions.map((warehouse) => (
              <option key={warehouse.id} value={warehouse.id}>
                {warehouse.name}
              </option>
            ))}
          </select>
          </WarehouseChoice>
        </label>

        <div className="flex items-end gap-2">
          <button
            type="button"
            onClick={downloadTemplate}
            disabled={!setup || isLoading}
            className="flex items-center gap-1.5 rounded-xl border border-nw-ok bg-nw-ok-bg px-3 py-2.5 font-bold text-nw-ok disabled:opacity-40"
          >
            <Download className="h-4 w-4" />
            تنزيل قالب Excel
          </button>
          <button
            type="button"
            onClick={() => fileInputRef.current?.click()}
            disabled={!setup || isLoading}
            className="flex items-center gap-1.5 rounded-xl bg-nw-primary px-3 py-2.5 font-bold text-nw-on-primary disabled:opacity-40"
          >
            <Upload className="h-4 w-4" />
            استيراد الملف
          </button>
          <input
            ref={fileInputRef}
            type="file"
            accept=".csv,.tsv,text/csv,text/tab-separated-values"
            className="hidden"
            onChange={(event) => {
              const file = event.target.files?.[0];
              if (file) void importTemplate(file);
            }}
          />
        </div>
      </div>

      <div className="rounded-xl border border-nw-warn/20 bg-nw-warn-bg p-3 text-[11px] leading-5 text-nw-warn">
        <FileSpreadsheet className="ml-1 inline h-4 w-4" />
        القالب بصيغة CSV المتوافقة مع Excel. لا تغيّر رمز الصنف؛ عبّئ فقط عدد الطرود
        والباكيتات المتبقية ثم احفظ الملف بصيغة CSV.
      </div>

      <div className="flex flex-col gap-2 sm:flex-row">
        <label className="relative flex-1">
          <Search className="absolute right-3 top-1/2 h-4 w-4 -translate-y-1/2 text-nw-muted" />
          <input
            value={searchQuery}
            onChange={(event) => setSearchQuery(event.target.value)}
            placeholder="ابحث باسم الصنف أو رمز الصنف أو الباركود..."
            className="w-full rounded-xl border border-nw-border bg-nw-bg py-2.5 pr-9 pl-3 text-nw-text focus:border-nw-info focus:outline-none"
          />
        </label>
        <button
          type="button"
          onClick={() => setEligibleOnly((current) => !current)}
          className={`rounded-xl border px-3 py-2.5 font-bold transition ${
            eligibleOnly
              ? 'border-nw-ok bg-nw-ok-bg text-nw-ok'
              : 'border-nw-border bg-nw-surface text-nw-text'
          }`}
        >
          المؤهل للتهيئة فقط
        </button>
      </div>

      {isLoading ? (
        <div className="flex min-h-52 items-center justify-center rounded-2xl border border-nw-border bg-nw-bg text-nw-muted">
          <Loader2 className="ml-2 h-5 w-5 animate-spin text-nw-info" />
          جاري تحميل الأصناف من Supabase...
        </div>
      ) : loadError ? (
        <div className="rounded-2xl border border-nw-bad bg-nw-bad-bg p-5 text-center text-nw-bad">
          <AlertTriangle className="mx-auto mb-2 h-6 w-6" />
          <p>{loadError}</p>
          <button
            type="button"
            onClick={() => void loadSetup()}
            className="mt-3 rounded-lg bg-nw-bad-bg px-4 py-2 font-bold text-nw-bad"
          >
            إعادة المحاولة
          </button>
        </div>
      ) : setup ? (
        <div className="max-h-[48vh] space-y-2 overflow-y-auto pl-1">
          {filteredProducts.map((product) => {
            const entry = entries[product.productId] || emptyEntry();
            const packages = integerValue(entry.packageCount);
            const loose = integerValue(entry.looseUnits);
            const actual =
              Number.isFinite(packages) && Number.isFinite(loose)
                ? packages * product.unitsPerPackage + loose
                : 0;
            const isSelected =
              entry.packageCount.trim() !== '' || entry.looseUnits.trim() !== '';
            const rowErrors =
              selectedRows.find((row) => row.product.productId === product.productId)
                ?.errors || [];

            return (
              <article
                key={product.productId}
                className={`rounded-2xl border p-3 transition ${
                  isSelected
                    ? rowErrors.length > 0
                      ? 'border-nw-bad bg-nw-bad-bg'
                      : 'border-nw-info bg-nw-info-bg'
                    : 'border-nw-border bg-nw-bg'
                } ${!product.eligible ? 'opacity-75' : ''}`}
              >
                <div className="flex flex-col gap-3 lg:flex-row lg:items-center">
                  <div className="min-w-0 flex-1">
                    <div className="flex flex-wrap items-center gap-2">
                      <h5 className="truncate font-black text-nw-text">
                        {product.productName}
                      </h5>
                      <span className="rounded-md bg-nw-surface-2 px-1.5 py-0.5 font-mono text-[9px] text-nw-muted">
                        {product.sku}
                      </span>
                      {!product.eligible && (
                        <span className="rounded-full bg-nw-bad-bg px-2 py-0.5 text-[9px] font-bold text-nw-bad">
                          استخدم الجرد
                        </span>
                      )}
                      {product.costPriceInMinorUnits <= 0 && (
                        <span className="rounded-full bg-nw-warn-bg px-2 py-0.5 text-[9px] font-bold text-nw-warn">
                          التكلفة ناقصة
                        </span>
                      )}
                    </div>
                    <p className="mt-1 text-[10px] text-nw-muted">
                      النظام الآن: {Math.floor(product.currentQuantity / product.unitsPerPackage)}{' '}
                      طرد +{' '}
                      {product.currentQuantity % product.unitsPerPackage}{' '}
                      {product.baseUnitName} ({product.currentQuantity} إجمالي)
                    </p>
                    {!product.eligible && (
                      <p className="mt-1 text-[10px] leading-4 text-nw-bad">
                        {product.blockReason}
                      </p>
                    )}
                  </div>

                  <div className="grid shrink-0 grid-cols-[1fr_1fr_auto] items-end gap-2">
                    <label className="space-y-1">
                      <span className="block text-[9px] font-bold text-nw-muted">
                        عدد طرد
                      </span>
                      <input inputMode="numeric" enterKeyHint="next"
                        type="number"
                        min="0"
                        step="1"
                        disabled={!product.eligible}
                        value={entry.packageCount}
                        onChange={(event) =>
                          updateEntry(
                            product.productId,
                            'packageCount',
                            event.target.value
                          )
                        }
                        placeholder="0"
                        className="w-full min-w-20 rounded-lg border border-nw-border bg-nw-surface px-2 py-2 text-center font-black text-nw-text disabled:cursor-not-allowed disabled:opacity-40"
                      />
                    </label>
                    <label className="space-y-1">
                      <span className="block text-[9px] font-bold text-nw-muted">
                        باقي {product.baseUnitName}
                      </span>
                      <input inputMode="numeric" enterKeyHint="next"
                        type="number"
                        min="0"
                        max={product.unitsPerPackage - 1}
                        step="1"
                        disabled={!product.eligible}
                        value={entry.looseUnits}
                        onChange={(event) =>
                          updateEntry(
                            product.productId,
                            'looseUnits',
                            event.target.value
                          )
                        }
                        placeholder="0"
                        className="w-full min-w-20 rounded-lg border border-nw-border bg-nw-surface px-2 py-2 text-center font-black text-nw-text disabled:cursor-not-allowed disabled:opacity-40"
                      />
                    </label>
                    <button
                      type="button"
                      disabled={!isSelected}
                      onClick={() => clearEntry(product.productId)}
                      className="mb-0.5 rounded-lg border border-nw-border p-2 text-nw-muted transition hover:text-nw-bad disabled:opacity-20"
                      aria-label={`مسح إدخال ${product.productName}`}
                    >
                      <X className="h-4 w-4" />
                    </button>
                  </div>
                </div>

                {isSelected && (
                  <div className="mt-2 flex flex-wrap items-center justify-between gap-2 border-t border-nw-border pt-2 text-[10px]">
                    <span className="font-bold text-nw-info">
                      الإجمالي المحسوب: {actual} {product.baseUnitName}
                    </span>
                    <span
                      className={
                        actual - product.currentQuantity >= 0
                          ? 'text-nw-ok'
                          : 'text-nw-bad'
                      }
                    >
                      الفرق عن النظام: {actual - product.currentQuantity > 0 ? '+' : ''}
                      {actual - product.currentQuantity}
                    </span>
                    {rowErrors.map((error) => (
                      <span key={error} className="w-full text-nw-bad">
                        {error}
                      </span>
                    ))}
                  </div>
                )}
              </article>
            );
          })}

          {filteredProducts.length === 0 && (
            <div className="rounded-2xl border border-nw-border p-8 text-center text-nw-muted">
              لا توجد أصناف مطابقة.
            </div>
          )}
        </div>
      ) : null}

      {setup && setup.recentSessions.length > 0 && (
        <details className="rounded-2xl border border-nw-border bg-nw-bg p-3">
          <summary className="flex cursor-pointer list-none items-center gap-2 font-bold text-nw-text">
            <History className="h-4 w-4 text-nw-info" />
            آخر جلسات المخزون الافتتاحي
          </summary>
          <div className="mt-3 space-y-2">
            {setup.recentSessions.map((session) => (
              <div
                key={session.id}
                className="flex items-center justify-between gap-3 rounded-xl border border-nw-border bg-nw-surface p-2.5"
              >
                <div>
                  <b className="text-nw-info">{session.sessionNumber}</b>
                  <span className="mt-0.5 block text-[9px] text-nw-muted">
                    {session.itemCount} صنف • {session.createdByName}
                  </span>
                </div>
                <div className="text-left text-[9px] text-nw-muted">
                  <span className="block">
                    {new Date(session.createdAt).toLocaleString('ar-JO')}
                  </span>
                  <span>الإجمالي: {session.totalActualQuantity}</span>
                </div>
              </div>
            ))}
          </div>
        </details>
      )}

      <label className="block space-y-1.5">
        <span className="font-bold text-nw-text">ملاحظة جلسة التهيئة *</span>
        <input
          value={notes}
          maxLength={500}
          onChange={(event) => setNotes(event.target.value)}
          className="w-full rounded-xl border border-nw-border bg-nw-bg px-3 py-2.5 text-nw-text focus:border-nw-info focus:outline-none"
        />
      </label>

      <div className="sticky bottom-0 -mx-5 -mb-5 border-t border-nw-border bg-nw-surface px-5 py-3 backdrop-blur">
        <div className="mb-2 grid grid-cols-3 gap-2 text-center">
          <div className="rounded-xl bg-nw-bg p-2">
            <span className="block text-[9px] text-nw-muted">الأصناف المدخلة</span>
            <b className="text-nw-text">{selectedRows.length}</b>
          </div>
          <div className="rounded-xl bg-nw-bg p-2">
            <span className="block text-[9px] text-nw-muted">إجمالي الباكيتات</span>
            <b className="text-nw-info">{totalActualQuantity}</b>
          </div>
          <div className="rounded-xl bg-nw-bg p-2">
            <span className="block text-[9px] text-nw-muted">فرق النظام</span>
            <b className={totalDifference >= 0 ? 'text-nw-ok' : 'text-nw-bad'}>
              {totalDifference > 0 ? '+' : ''}{totalDifference}
            </b>
          </div>
        </div>
        {invalidRows.length > 0 && (
          <p className="mb-2 text-center text-[10px] font-bold text-nw-bad">
            صحح {invalidRows.length} صف قبل المتابعة.
          </p>
        )}
        <button
          type="button"
          disabled={
            selectedRows.length === 0 ||
            invalidRows.length > 0 ||
            notes.trim().length < 5 ||
            isLoading
          }
          onClick={() => setShowReview(true)}
          className="flex w-full items-center justify-center gap-2 rounded-xl bg-nw-primary py-3 font-black text-nw-on-primary shadow-lg transition hover:bg-nw-primary disabled:cursor-not-allowed disabled:opacity-40"
        >
          <ClipboardCheck className="h-4 w-4" />
          مراجعة واعتماد المخزون الافتتاحي
        </button>
      </div>

      {showReview && (
        <div className="fixed inset-0 z-[70] flex items-end justify-center bg-nw-side/80 p-0 backdrop-blur-sm sm:items-center sm:p-4">
          <div ref={reviewPanel as React.RefObject<HTMLDivElement>} tabIndex={-1}
            role="dialog" aria-modal="true" aria-label="تأكيد الجرد الافتتاحي" aria-busy={isSubmitting}
            className="w-full max-w-lg space-y-4 rounded-t-3xl border border-nw-border bg-nw-surface p-5 shadow-2xl sm:rounded-3xl">
            <div className="flex items-start gap-3">
              <div className="flex h-10 w-10 shrink-0 items-center justify-center rounded-2xl bg-nw-ok-bg text-nw-ok">
                <ShieldCheck className="h-5 w-5" />
              </div>
              <div>
                <h4 className="font-black text-nw-text">تأكيد الجرد الافتتاحي</h4>
                <p className="mt-1 text-[11px] leading-5 text-nw-muted">
                  سيتم ضبط الكمية الفعلية لـ{selectedRows.length} صنف داخل{' '}
                  {setup?.warehouse.name}. العملية ذرية ومسجلة ولا تنشئ حساب مورد.
                </p>
              </div>
            </div>

            <div className="grid grid-cols-2 gap-2">
              <div className="rounded-xl border border-nw-border bg-nw-bg p-3 text-center">
                <span className="block text-[10px] text-nw-muted">الإجمالي بعد الاعتماد</span>
                <b className="text-lg text-nw-info">{totalActualQuantity}</b>
              </div>
              <div className="rounded-xl border border-nw-border bg-nw-bg p-3 text-center">
                <span className="block text-[10px] text-nw-muted">صافي التغيير</span>
                <b className={totalDifference >= 0 ? 'text-lg text-nw-ok' : 'text-lg text-nw-bad'}>
                  {totalDifference > 0 ? '+' : ''}{totalDifference}
                </b>
              </div>
            </div>

            <div className="rounded-xl border border-nw-warn/40 bg-nw-warn-bg p-3 text-[11px] leading-5 text-nw-warn">
              <AlertTriangle className="ml-1 inline h-4 w-4" />
              هل أنهيتم العد الفعلي؟ بعد بدء المبيعات أو الاستلام تصبح أي فروقات
              لاحقة من خلال شاشة الجرد المعتادة.
            </div>

            <div className="grid grid-cols-2 gap-2">
              <button
                type="button"
                disabled={isSubmitting}
                onClick={() => void handleApply()}
                className="flex items-center justify-center gap-2 rounded-xl bg-nw-ok-bg py-3 font-black text-nw-ok disabled:opacity-50"
              >
                {isSubmitting ? (
                  <Loader2 className="h-4 w-4 animate-spin" />
                ) : (
                  <PackageCheck className="h-4 w-4" />
                )}
                {isSubmitting ? 'جاري الاعتماد...' : 'نعم، اعتمد الجرد'}
              </button>
              <button
                type="button"
                disabled={isSubmitting}
                onClick={() => setShowReview(false)}
                className="rounded-xl border border-nw-border bg-nw-surface-2 py-3 font-bold text-nw-text"
              >
                عودة للمراجعة
              </button>
            </div>
          </div>
        </div>
      )}

      <div className="flex items-center justify-center gap-2 text-[10px] text-nw-muted">
        <CheckCircle2 className="h-3.5 w-3.5 text-nw-ok" />
        محفوظ عبر PostgreSQL RPC وسجل التدقيق
        <button type="button" onClick={onClose} className="text-nw-muted underline">
          إغلاق
        </button>
      </div>
    </div>
  );
};

src/utils/orderPresentation.ts.beforeText:
export function formatOperationalOrderContents(
  firstProductName: string,
  itemCount: number
): string {
  const productName = firstProductName.trim();
  const safeItemCount = Math.max(0, Math.floor(itemCount || 0));

  if (!productName) {
    if (safeItemCount === 0) return 'طلب بدون أصناف';
    if (safeItemCount === 1) return 'طلب بصنف واحد';
    return `طلب يحتوي ${safeItemCount.toLocaleString('ar-JO')} أصناف`;
  }

  const additionalCount = Math.max(0, safeItemCount - 1);
  if (additionalCount === 0) return productName;
  if (additionalCount === 1) return `${productName} + صنف إضافي`;
  if (additionalCount === 2) return `${productName} + صنفان إضافيان`;
  if (additionalCount <= 10) {
    return `${productName} + ${additionalCount.toLocaleString('ar-JO')} أصناف إضافية`;
  }
  return `${productName} + ${additionalCount.toLocaleString('ar-JO')} صنفًا إضافيًا`;
}

src/utils/receipt.ts.beforeText:
import type { OrderItem,PaymentMethod } from '../types';
import {receiptLineDescription} from '../../customer-web/src/receipts/commercialReceipt';
import {exchangeFundingLines,type ExchangeReceiptFunding} from '../../customer-web/src/receipts/exchangeFunding';
import {formatExactMinorJod} from '../../customer-web/src/receipts/exactMoney';

export interface ReceiptShareItem {
  productName: string;
  quantity: number;
  salePackage?: string;
  unit?: string;
  totalPrice: number;
  commercialLineKind?:string;
  baseQuantity?:number;
  baseUnitName?:string;
  parcelInstances?:OrderItem['parcelInstances'];
}

export interface ReceiptShareInput {
  actualUnitNames?:boolean;
  businessName: string;
  branchName: string;
  invoiceNumber: string;
  customerName: string;
  createdAt: string;
  items: ReceiptShareItem[];
  subtotal: number;
  discount: number;
  totalAmount: number;
  paymentMethod: PaymentMethod;
  paidAmount: number;
  initialPaymentMethod?: 'cash'|'cliq';
  remainingAmount: number;
  changeDue: number;
  publicReceiptUrl?: string;
  exchangeFunding?: ExchangeReceiptFunding;
}

export function paymentMethodLabel(method: PaymentMethod, initial?:'cash'|'cliq'): string {
  const label = (
    {
      cash: 'كاش',
      cash_on_delivery: 'كاش عند الاستلام',
      cliq: 'CliQ',
      card: 'بطاقة',
      bank_transfer: 'تحويل بنكي',
      debt: 'آجل على حساب العميل',
      mixed: 'دفع مختلط',
      exchange_credit: 'تبديل · مقابل داخلي',
    }[method] || method
  );
  return initial&&method==='debt'?label+' · دفعة '+(initial==='cash'?'كاش':'CliQ'):label;
}

const money = (value: number) => `${value.toFixed(3)} د.أ`;

export function buildReceiptShareText(input: ReceiptShareInput): string {
  if(input.paymentMethod==='exchange_credit'&&(!input.exchangeFunding||input.items.length!==1))throw new Error('تفصيل مقابل التبديل غير مكتمل؛ حدّث الفاتورة قبل مشاركة الوصل.');
  const lines = input.items.map(
    (item) =>
      `• ${item.productName}: ${receiptLineDescription({actualUnitNames:input.actualUnitNames,key:'',name:item.productName,kind:item.commercialLineKind,quantity:item.quantity,
        baseQuantity:item.baseQuantity,baseUnitName:item.baseUnitName,savedUnitName:input.actualUnitNames?item.salePackage||item.unit:item.unit||item.salePackage||'طرد',
        parcels:item.parcelInstances?.map(p=>({components:p.components.map(c=>({name:c.name,quantity:c.quantity,unitName:c.unitName}))})),
        totalInMinorUnits:Math.round(item.totalPrice*1000)})} - ${input.exchangeFunding?formatExactMinorJod(input.exchangeFunding.newTotalInMinorUnits):money(item.totalPrice)}`
  );

  return [
    input.businessName,
    input.branchName,
    `إيصال البيع رقم: ${input.invoiceNumber}`,
    `التاريخ: ${new Date(input.createdAt).toLocaleString('ar-JO')}`,
    `العميل: ${input.customerName || 'زبون نقدي'}`,
    '',
    ...lines,
    '',
    `المجموع الفرعي: ${input.exchangeFunding?formatExactMinorJod(input.exchangeFunding.newTotalInMinorUnits):money(input.subtotal)}`,
    input.discount > 0 ? `الخصم: ${money(input.discount)}` : '',
    `الإجمالي: ${input.exchangeFunding?formatExactMinorJod(input.exchangeFunding.newTotalInMinorUnits):money(input.totalAmount)}`,
    `طريقة الدفع: ${paymentMethodLabel(input.paymentMethod,input.initialPaymentMethod)}`,
    ...(!input.exchangeFunding?[`المدفوع: ${money(input.paidAmount)}`]:[]),
    ...(input.exchangeFunding?exchangeFundingLines(input.exchangeFunding):[]),
    input.remainingAmount > 0
      ? `${input.initialPaymentMethod?'الباقي على الحساب':'المتبقي على العميل'}: ${money(input.remainingAmount)}`
      : '',
    input.changeDue > 0 ? `الباقي للعميل: ${money(input.changeDue)}` : '',
    input.publicReceiptUrl ? `رابط الإيصال الإلكتروني: ${input.publicReceiptUrl}` : '',
    '',
    'شكرًا لتعاملكم مع النواصرة لتجارة الجملة والمواد الغذائية.',
  ]
    .filter((line) => line !== '')
    .join('\n');
}

tests/price-visibility-history.test.ts.beforeText:
import test from 'node:test';
import assert from 'node:assert/strict';
import {readFileSync} from 'node:fs';
import {execFileSync} from 'node:child_process';
import {createHash} from 'node:crypto';
import {sourceBeforePriceVisibility,restorePriceVisibilityHashes,pathsBeforePriceVisibility} from '../scripts/audit/source-before-price-visibility.mjs';
const file='customer-web/src/components/ProductCard.tsx';
const hash=(s:string)=>createHash('sha256').update(s.replaceAll('\r\n','\n')).digest('hex');
test('price layout inverse binds the OFF redesign and preserves the original exact three CSS inverse and every unknown byte',()=>{
 const raw=readFileSync(file,'utf8'),before=execFileSync('git',['show','0bd3b5b0fd149c9e92d802c6dabb55b236c127cc:'+file],{encoding:'utf8',maxBuffer:1024**2}).replaceAll('\r\n','\n');
 assert.equal(sourceBeforePriceVisibility(file,raw),before);
 assert.equal(sourceBeforePriceVisibility(file,raw+'\n// unknown byte'),raw+'\n// unknown byte');
 assert.equal(sourceBeforePriceVisibility(file,null),null);assert.equal(sourceBeforePriceVisibility('unknown',raw),raw);
 assert.deepEqual(restorePriceVisibilityHashes([{file,sha256:hash(raw)}]),[{file,sha256:hash(before)}]);
 assert.deepEqual(restorePriceVisibilityHashes([{file,sha256:hash(raw+'x')}]),[{file,sha256:hash(raw+'x')}]);
 const pin=JSON.parse(readFileSync('scripts/audit/price-visibility-source-pin.json','utf8'));
 const prior=execFileSync('git',['show','5b5e07bfe259cb04048dc9baef789aeee7a054c2:'+file],{encoding:'utf8',maxBuffer:1024**2}).replaceAll('\r\n','\n');
 assert.equal(pin.hunks.length,3);assert.equal(pin.before,hash(before));assert.equal(pin.after,hash(prior));
 assert.equal(sourceBeforePriceVisibility(file,prior),before);
 assert.equal(pin.files[file].before,hash(before));assert.equal(pin.files[file].after,hash(raw));
});

test('price evidence projection restores exact prior Git bytes;new artifacts are hash-bound and unknown text remains visible',()=>{
 const pin=JSON.parse(readFileSync('scripts/audit/price-visibility-source-pin.json','utf8'));
 assert.equal(pin.baseline,'0bd3b5b0fd149c9e92d802c6dabb55b236c127cc');
 for(const [path,entry] of Object.entries(pin.files) as [string,{before:string|null;after:string;binary?:boolean}][]){
  const bytes=readFileSync(path),raw=bytes.toString('utf8');
  assert.equal(entry.binary?createHash('sha256').update(bytes).digest('hex'):hash(raw),entry.after,path);
  if(entry.binary){assert.equal(entry.before,null);assert.deepEqual(pathsBeforePriceVisibility([path]),[]);continue;}
  let before=null;try{before=execFileSync('git',['show',pin.baseline+':'+path],{encoding:'utf8',stdio:['ignore','pipe','pipe'],maxBuffer:32*1024**2}).replaceAll('\r\n','\n');}catch{assert.equal(entry.before,null,path);}
  assert.equal(sourceBeforePriceVisibility(path,raw),before,path);
  assert.equal(sourceBeforePriceVisibility(path,raw+'\nUNKNOWN_BYTE'),raw+'\nUNKNOWN_BYTE',path);
  if(entry.before===null)assert.deepEqual(pathsBeforePriceVisibility([path]),[]);
 }
});
